package com.earchives.mcp.adapter.auth;
import com.earchives.mcp.adapter.config.AdapterSecurityProperties;import com.earchives.mcp.adapter.exception.McpAuthException;import com.earchives.mcp.adapter.security.CryptoService;import com.earchives.mcp.adapter.state.RedisStateService;import jakarta.servlet.http.HttpServletRequest;import org.junit.jupiter.api.Test;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.Duration;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** HMAC 测试覆盖合法个人微信请求、正文替换和 nonce 重放三个主要攻击面。 */
class WechatSignatureServiceTest{
 private static final String SECRET="unit-test-signing-secret";
 private record Fixture(WechatSignatureService service,RedisStateService state,CryptoService crypto,AdapterSecurityProperties properties){}
 private Fixture fixture(){AdapterSecurityProperties p=new AdapterSecurityProperties();p.getSecurity().setSignatureSkew(Duration.ofMinutes(5));p.getSecurity().setDataEncryptionKey(Base64.getEncoder().encodeToString(new byte[32]));CryptoService c=new CryptoService(p);c.validateKey();RedisStateService state=mock(RedisStateService.class);when(state.claimNonce(anyString(),anyString())).thenReturn(true);return new Fixture(new WechatSignatureService(p,state,c),state,c,p);}
 /** 正确签名必须解析出 wechat 主体，且持久化标识只能是摘要。 */
 @Test void validSignatureCreatesHashedPrincipal()throws Exception{Fixture f=fixture();byte[] body="{\"jsonrpc\":\"2.0\"}".getBytes(StandardCharsets.UTF_8);HttpServletRequest r=request(body,"nonce-1234567890123456");ChannelPrincipal p=f.service.verify(r,body,client());assertEquals("wechat",p.channel());assertNotEquals("wx-user-A",p.principalHash());}
 /** 签名后替换 JSON 工具参数会改变正文摘要，必须在工具执行前拒绝。 */
 @Test void changedBodyIsRejected()throws Exception{Fixture f=fixture();byte[] signed="{\"a\":1}".getBytes(StandardCharsets.UTF_8);HttpServletRequest r=request(signed,"nonce-1234567890123456");assertThrows(McpAuthException.class,()->f.service.verify(r,"{\"a\":2}".getBytes(StandardCharsets.UTF_8),client()));}
 /** Redis 声明 nonce 已存在时视为重放，即使 HMAC 本身仍然正确也必须拒绝。 */
 @Test void replayedNonceIsRejected()throws Exception{Fixture f=fixture();when(f.state.claimNonce(anyString(),anyString())).thenReturn(false);byte[] body="{}".getBytes(StandardCharsets.UTF_8);HttpServletRequest r=request(body,"nonce-1234567890123456");assertThrows(McpAuthException.class,()->f.service.verify(r,body,client()));}
 private AuthContext client(){return new AuthContext("client","test","hash",SECRET,Set.of("*"));}
 private HttpServletRequest request(byte[] body,String nonce)throws Exception{long ts=System.currentTimeMillis()/1000;HttpServletRequest r=mock(HttpServletRequest.class);when(r.getHeader(WechatSignatureService.CHANNEL)).thenReturn("wechat");when(r.getHeader(WechatSignatureService.USER)).thenReturn("wx-user-A");when(r.getHeader(WechatSignatureService.TIMESTAMP)).thenReturn(String.valueOf(ts));when(r.getHeader(WechatSignatureService.NONCE)).thenReturn(nonce);when(r.getHeader(WechatSignatureService.SESSION)).thenReturn("session-1");String hash=Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(body));String canonical=String.join("\n","v1","POST","/mcp","wechat","wx-user-A","session-1",String.valueOf(ts),nonce,hash);Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));when(r.getHeader(WechatSignatureService.SIGNATURE)).thenReturn("v1="+Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8))));return r;}
}